package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.query.Binding;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;

/** The shared projection of {@link NativeBindingSetProjectionStep} against its row-by-row projection. */
class NativeBindingSetProjectionCompactTest {

	private static final String[] SOURCES = { "a", "b", "c" };
	private static final String[] TARGETS = { "x", "y", "z" };

	@Test
	void compactProjectionEqualsTheRowByRowProjectionInContentAndOrder() {
		MapBindingSet parent = bindings("b", RDF.BAG, "other", RDF.LIST);
		List<BindingSet> sources = List.of(bindings("a", RDF.ALT, "b", RDF.FIRST, "c", RDF.REST),
				bindings("c", RDF.REST, "a", RDF.ALT), bindings("c", RDF.REST), bindings("unrelated", RDF.NIL),
				new MapBindingSet());
		for (boolean includeAllParentBindings : new boolean[] { false, true }) {
			BindingSet rowParent = includeAllParentBindings ? EmptyBindingSet.getInstance() : parent;
			MapBindingSet.CompactLayout targets = NativeBindingSetProjectionStep.compactTargets(rowParent, TARGETS,
					includeAllParentBindings);
			assertThat(targets).isNotNull();
			Value[] parentValues = NativeBindingSetProjectionStep.parentValues(rowParent, SOURCES,
					includeAllParentBindings);
			for (BindingSet source : sources) {
				BindingSet expected = NativeBindingSetProjectionStep.project(source, rowParent, SOURCES, TARGETS,
						includeAllParentBindings);
				BindingSet compact = NativeBindingSetProjectionStep.projectCompact(source, SOURCES, parentValues,
						targets);
				assertThat(compact).isEqualTo(expected).isExactlyInstanceOf(MapBindingSet.class);
				assertThat(names(compact)).isEqualTo(names(expected));
				assertThat(compact.getBindingNames()).containsExactlyElementsOf(expected.getBindingNames());
			}
		}
	}

	@Test
	void rowsOfOneProjectionDoNotShareTheirChanges() {
		MapBindingSet.CompactLayout targets = NativeBindingSetProjectionStep.compactTargets(
				EmptyBindingSet.getInstance(), TARGETS, false);
		Value[] parentValues = NativeBindingSetProjectionStep.parentValues(EmptyBindingSet.getInstance(), SOURCES,
				false);
		MapBindingSet first = (MapBindingSet) NativeBindingSetProjectionStep.projectCompact(
				bindings("a", RDF.ALT, "b", RDF.BAG), SOURCES, parentValues, targets);
		MapBindingSet second = (MapBindingSet) NativeBindingSetProjectionStep.projectCompact(
				bindings("a", RDF.ALT, "b", RDF.BAG), SOURCES, parentValues, targets);

		first.setBinding("z", RDF.NIL);
		first.removeBinding("x");

		assertThat(second.getBindingNames()).containsExactly("x", "y");
		assertThat(second.getValue("x")).isSameAs(RDF.ALT);
	}

	@Test
	void parentBindingsInFrontOrARepeatedTargetAreProjectedRowByRow() {
		assertThat(NativeBindingSetProjectionStep.compactTargets(bindings("p", RDF.NIL), TARGETS, true)).isNull();
		assertThat(NativeBindingSetProjectionStep.compactTargets(EmptyBindingSet.getInstance(),
				new String[] { "x", "y", "x" }, false)).isNull();
		assertThat(NativeBindingSetProjectionStep.compactTargets(bindings("p", RDF.NIL), TARGETS, false)).isNotNull();
	}

	private static List<String> names(BindingSet bindings) {
		List<String> names = new ArrayList<>();
		for (Binding binding : bindings) {
			names.add(binding.getName());
		}
		return names;
	}

	private static MapBindingSet bindings(Object... namesAndValues) {
		MapBindingSet bindings = new MapBindingSet();
		for (int i = 0; i < namesAndValues.length; i += 2) {
			bindings.addBinding((String) namesAndValues[i], (Value) namesAndValues[i + 1]);
		}
		return bindings;
	}
}
